using Microsoft.EntityFrameworkCore; using pcms.Application.Inventory; using pcms.Domain.Entities; using pcms.Infrastructure.Persistence;
namespace pcms.Infrastructure.Services;
public class UrnBomService(AppDbContext db):IUrnBomService
{
 public async Task<IEnumerable<BomDto>> GetAsync(Guid urnId,bool includeCost){var bs=await db.UrnBillOfMaterials.AsNoTracking().Include(x=>x.Urn).Include(x=>x.Items).ThenInclude(x=>x.SupplyItem).Where(x=>x.UrnId==urnId).OrderByDescending(x=>x.Version).ToListAsync();return await Task.WhenAll(bs.Select(x=>Map(x,includeCost)));}
 public async Task<BomDto> SaveAsync(BomInput input){if(input.Items.Count==0||input.Items.Any(x=>x.RequiredQuantity<=0||string.IsNullOrWhiteSpace(x.UnitOfMeasure))||input.Items.GroupBy(x=>x.SupplyItemId).Any(x=>x.Count()>1))throw new ArgumentException("La lista requiere partidas únicas con cantidades válidas.");var urn=await db.Urns.FirstOrDefaultAsync(x=>x.Id==input.UrnId&&x.IsActive)??throw new ArgumentException("La urna no existe o está inactiva.");var ids=input.Items.Select(x=>x.SupplyItemId).ToArray();var valid=await db.SupplyItems.Where(x=>ids.Contains(x.Id)&&x.IsActive).Select(x=>x.Id).ToListAsync();if(valid.Count!=ids.Length)throw new ArgumentException("Solo se pueden asignar insumos activos.");await using var tx=await db.Database.BeginTransactionAsync();await db.UrnBillOfMaterials.Where(x=>x.UrnId==input.UrnId&&x.IsActive).ExecuteUpdateAsync(x=>x.SetProperty(y=>y.IsActive,false).SetProperty(y=>y.UpdatedAt,DateTime.UtcNow));var version=(await db.UrnBillOfMaterials.Where(x=>x.UrnId==input.UrnId).MaxAsync(x=>(int?)x.Version)??0)+1;var bom=new UrnBillOfMaterials{Id=Guid.NewGuid(),UrnId=urn.Id,Version=version,CreatedAt=DateTime.UtcNow};bom.Items=input.Items.Select(i=>new UrnBillOfMaterialsItem{Id=Guid.NewGuid(),SupplyItemId=i.SupplyItemId,RequiredQuantity=decimal.Round(i.RequiredQuantity,3),UnitOfMeasure=i.UnitOfMeasure.Trim()}).ToList();db.Add(bom);await db.SaveChangesAsync();await tx.CommitAsync();return (await Map(await db.UrnBillOfMaterials.Include(x=>x.Urn).Include(x=>x.Items).ThenInclude(x=>x.SupplyItem).FirstAsync(x=>x.Id==bom.Id),false));}
 async Task<BomDto> Map(UrnBillOfMaterials b,bool cost){var rows=new List<BomItemDto>();foreach(var i in b.Items){decimal? unit=null;string? cur=null;if(cost){var s=await db.SupplierSupplyItems.AsNoTracking().Where(x=>x.SupplyItemId==i.SupplyItemId&&x.IsActive&&x.IsPreferred&&x.InventoryUnitsPerPurchaseUnit>0).SingleOrDefaultAsync();if(s is not null){unit=s.CurrentUnitCost/s.InventoryUnitsPerPurchaseUnit;cur=s.Currency;}var f=await db.FilamentSpecifications.AsNoTracking().FirstOrDefaultAsync(x=>x.SupplyItemId==i.SupplyItemId);if(f is not null&&unit is not null&&i.UnitOfMeasure.Equals("g",StringComparison.OrdinalIgnoreCase)){} }var line=unit.HasValue?decimal.Round(unit.Value*i.RequiredQuantity,4):(decimal?)null;rows.Add(new(i.Id,i.SupplyItemId,i.SupplyItem.Name,i.RequiredQuantity,i.UnitOfMeasure,line,cur,line.HasValue));}var complete=rows.All(x=>x.CostAvailable);var currencies=rows.Where(x=>x.Currency is not null).Select(x=>x.Currency!).Distinct().ToList();return new(b.Id,b.UrnId,b.Urn.Name,b.Version,b.IsActive,rows,complete?decimal.Round(rows.Sum(x=>x.EstimatedCost!.Value),4):(decimal?)null,complete&&currencies.Count<=1,currencies.SingleOrDefault());}
}
